template <int NQ>
__device__ __forceinline__ void ikp_attn_body(const InkAttnArgs& a, const int nsplit, const int bx, const int bz) {
    extern __shared__ __align__(16) unsigned char smraw[];
    const int warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
    const int kvh = blockIdx.y;
    const int t0 = bz * 16;
    const int mt = min(16, a.M - t0);
    const int nq = 3 * mt;
    const int qcap = 3 * min(16, a.M);                                // same for every CTA of the launch
    float* sQ = reinterpret_cast<float*>(smraw);                     // [qcap][128]
    float* sR = sQ + qcap * IKA_HD;                                   // [qcap][16]
    float* sP = sR + qcap * IKA_DREL;                                 // [16][80] proj columns
    __half* sK = reinterpret_cast<__half*>(sP + IKA_DREL * 80);       // [64][130]
    __half* sV = sK + IKA_SUB * IKA_KSTR;                             // [64][128]

    for (int i = threadIdx.x; i < nq * IKA_HD; i += blockDim.x) {
        const int qi = i / IKA_HD, d = i % IKA_HD;
        const int t = t0 + qi / 3, h = 3 * kvh + qi % 3;
        sQ[i] = a.Qf[((size_t)t * NQ + h) * IKA_HD + d];
    }
    for (int i = threadIdx.x; i < nq * IKA_DREL; i += blockDim.x) {
        const int qi = i / IKA_DREL, d = i % IKA_DREL;
        const int t = t0 + qi / 3, h = 3 * kvh + qi % 3;
        sR[i] = a.Rf[((size_t)t * NQ + h) * IKA_DREL + d];
    }
    const int P0 = a.p0 + t0, P1 = P0 + mt - 1;
    const int kmin = a.window ? max(0, P0 - a.window + 1) : 0;
    const long long cs = (long long)(a.c0 + bx) * a.chunk;
    const int lo = (int)max((long long)kmin, cs);
    const int hi = (int)min((long long)P1 + 1, cs + a.chunk);       // exclusive
    const float scale = rsqrtf((float)IKA_HD);

    float m_run[IKA_QPW], l_run[IKA_QPW], acc[IKA_QPW][4];
    #pragma unroll
    for (int j = 0; j < IKA_QPW; ++j) {
        m_run[j] = -INFINITY; l_run[j] = 0.f;
        #pragma unroll
        for (int d = 0; d < 4; ++d) acc[j][d] = 0.f;
    }
    for (int kb = (lo / IKA_SUB) * IKA_SUB; kb < hi; kb += IKA_SUB) {
        __syncthreads();
        // K / V subtile (rows outside [lo, hi) are zero: never read uninitialised cache)
        for (int i = threadIdx.x; i < IKA_SUB * 64; i += blockDim.x) {
            const int r = i >> 6, w2 = i & 63;     // 64 half2 per row
            const int kp = kb + r;
            __half2 kv2 = __float2half2_rn(0.f), vv2 = __float2half2_rn(0.f);
            if (kp >= lo && kp < hi) {
                const size_t base = (size_t)(kp & a.cap_mask) * IKP_KVW(NQ) + kvh * IKA_HD + 2 * w2;
                kv2 = *reinterpret_cast<const __half2*>(a.kc + base);
                vv2 = *reinterpret_cast<const __half2*>(a.vc + base);
            }
            *reinterpret_cast<__half2*>(sK + r * IKA_KSTR + 2 * w2) = kv2;
            *reinterpret_cast<__half2*>(sV + r * IKA_HD + 2 * w2) = vv2;
        }
        // proj columns for distances dmin .. dmin+79 (dmin = P0 - (kb + 63))
        const int dmin = P0 - (kb + IKA_SUB - 1);
        for (int i = threadIdx.x; i < IKA_DREL * 80; i += blockDim.x) {
            const int dd = i / 80, c = i % 80;
            const int dist = dmin + c;
            sP[i] = (dist >= 0 && dist < a.ext) ? a.proj[(size_t)dd * a.ext + dist] : 0.f;
        }
        __syncthreads();
        #pragma unroll
        for (int j = 0; j < IKA_QPW; ++j) {
            const int qi = warp + 8 * j;
            if (qi >= nq) break;
            const int P = P0 + qi / 3;
            const float* q = sQ + qi * IKA_HD;
            const float* rr = sR + qi * IKA_DREL;
            float s[2];
            #pragma unroll
            for (int u = 0; u < 2; ++u) {
                const int r = lane + 32 * u, kp = kb + r;
                const __half2* kr = reinterpret_cast<const __half2*>(sK + r * IKA_KSTR);
                float dot = 0.f;
                #pragma unroll 16
                for (int d2 = 0; d2 < IKA_HD / 2; ++d2) {
                    const float2 kf = __half22float2(kr[d2]);
                    dot = fmaf(q[2 * d2], kf.x, dot);
                    dot = fmaf(q[2 * d2 + 1], kf.y, dot);
                }
                const int dist = P - kp;
                float b = 0.f;
                const int col = dist - dmin;
                #pragma unroll
                for (int dd = 0; dd < IKA_DREL; ++dd) b = fmaf(rr[dd], sP[dd * 80 + col], b);
                const bool ok = kp >= lo && kp < hi && dist >= 0 && (a.window == 0 || dist < a.window);
                s[u] = ok ? fmaf(dot, scale, b) : -INFINITY;
            }
            const float msub = ika_wmax(fmaxf(s[0], s[1]));
            if (msub == -INFINITY) continue;          // nothing visible here: state untouched
            const float mnew = fmaxf(m_run[j], msub);
            const float fold = __expf(m_run[j] - mnew); // m_run = -inf -> 0
            const float e0 = __expf(s[0] - mnew), e1 = __expf(s[1] - mnew);
            l_run[j] = l_run[j] * fold + ika_wsum(e0 + e1);
            m_run[j] = mnew;
            float o0 = acc[j][0] * fold, o1 = acc[j][1] * fold, o2 = acc[j][2] * fold, o3 = acc[j][3] * fold;
            #pragma unroll 8
            for (int r = 0; r < IKA_SUB; ++r) {
                const float pr = __shfl_sync(0xffffffffu, r < 32 ? e0 : e1, r & 31);
                const uint2 vv = *reinterpret_cast<const uint2*>(sV + r * IKA_HD + 4 * lane);
                const float2 va = __half22float2(*reinterpret_cast<const __half2*>(&vv.x));
                const float2 vb = __half22float2(*reinterpret_cast<const __half2*>(&vv.y));
                o0 = fmaf(pr, va.x, o0); o1 = fmaf(pr, va.y, o1); o2 = fmaf(pr, vb.x, o2); o3 = fmaf(pr, vb.y, o3);
            }
            acc[j][0] = o0; acc[j][1] = o1; acc[j][2] = o2; acc[j][3] = o3;
        }
    }
    #pragma unroll
    for (int j = 0; j < IKA_QPW; ++j) {
        const int qi = warp + 8 * j;
        if (qi >= nq) break;
        const int t = t0 + qi / 3, h = 3 * kvh + qi % 3;
        if (nsplit == 1) {
            const float* y = a.Y + (size_t)t * a.ldy;
            const float sink = y[a.os + h];
            const float m = fmaxf(m_run[j], sink);
            const float fold = __expf(m_run[j] - m);
            const float inv = 1.0f / (l_run[j] * fold + __expf(sink - m));
            const float w = fold * inv;
            if (a.og < 0) {
                float* fp = reinterpret_cast<float*>(a.out) + (size_t)t * NQ * IKA_HD + h * IKA_HD + 4 * lane;
                *reinterpret_cast<float4*>(fp) = make_float4(acc[j][0] * w, acc[j][1] * w, acc[j][2] * w, acc[j][3] * w);
            } else {
                const float4 gt = *reinterpret_cast<const float4*>(y + a.og + h * IKA_HD + 4 * lane);
                uint16_t* o = a.out + (size_t)t * NQ * IKA_HD + h * IKA_HD + 4 * lane;
                uint2 pk;
                pk.x = (uint32_t)ika_f2b(acc[j][0] * w * ika_sig(gt.x)) | ((uint32_t)ika_f2b(acc[j][1] * w * ika_sig(gt.y)) << 16);
                pk.y = (uint32_t)ika_f2b(acc[j][2] * w * ika_sig(gt.z)) | ((uint32_t)ika_f2b(acc[j][3] * w * ika_sig(gt.w)) << 16);
                *reinterpret_cast<uint2*>(o) = pk;
            }
        } else {
            const size_t pi = ((size_t)t * NQ + h) * nsplit + bx;
            if (lane == 0) { a.pm[pi] = m_run[j]; a.pl[pi] = l_run[j]; }
            *reinterpret_cast<float4*>(a.pacc + pi * IKA_HD + 4 * lane) = make_float4(acc[j][0], acc[j][1], acc[j][2], acc[j][3]);
        }
    }
}

template <int NQ>
__device__ __forceinline__ void ikp_attn_combine_body(const InkAttnArgs& a, const int nsplit, const int t) {
    const int h = blockIdx.y, d = threadIdx.x;
    const float* y = a.Y + (size_t)t * a.ldy;
    const float sink = y[a.os + h];
    const size_t pb = ((size_t)t * NQ + h) * nsplit;
    float m = sink;
    for (int c = 0; c < nsplit; ++c) if (a.pl[pb + c] > 0.f) m = fmaxf(m, a.pm[pb + c]);
    float sum = __expf(sink - m), o = 0.f;
    for (int c = 0; c < nsplit; ++c) {
        const float l = a.pl[pb + c];
        if (!(l > 0.f)) continue;
        const float f = __expf(a.pm[pb + c] - m);
        sum = fmaf(l, f, sum);
        o = fmaf(a.pacc[(pb + c) * IKA_HD + d], f, o);
    }
    if (a.og < 0) {
        reinterpret_cast<float*>(a.out)[(size_t)t * NQ * IKA_HD + h * IKA_HD + d] = o / sum;
    } else {
        a.out[(size_t)t * NQ * IKA_HD + h * IKA_HD + d] = ika_f2b(o / sum * ika_sig(y[a.og + h * IKA_HD + d]));
    }
}

template <int NQ, bool SP>
__device__ __forceinline__ void ikp_attn_tc2_body(const InkAttnArgs& a) {
    extern __shared__ __align__(16) unsigned char smraw[];
    __half* sK = reinterpret_cast<__half*>(smraw);
    __half* sV = sK + 64 * IKT_KS;
    uint16_t* sPJ = reinterpret_cast<uint16_t*>(sV + 64 * IKT_KS);
    float* sB = reinterpret_cast<float*>(sPJ + IKT2_NB * IKT_PJS);
    __half* sQl = reinterpret_cast<__half*>(sB + 6 * 16 * IKT_NB);
    const int warp = threadIdx.x >> 5, lane = threadIdx.x & 31, gid = lane >> 2, tig = lane & 3;
    const int nsplit = gridDim.x, kvh = blockIdx.y;
    const int tt = warp / 3;                                   // this warp's token tile (0 / 1)
    const int tc0 = blockIdx.z * 32;                            // the CTA's first token
    const int mtc = min(32, a.M - tc0);                         // the CTA's tokens
    const int t0 = tc0 + 16 * tt;
    const int mt = min(16, a.M - t0);                           // <= 0: an empty second tile (its warps only stage)
    const int nq = max(0, 3 * mt);
    const int P0c = a.p0 + tc0, P1 = P0c + mtc - 1;
    const int P0 = a.p0 + t0;
    const int kmin = a.window ? max(0, P0c - a.window + 1) : 0;
    const long long cs = (long long)(a.c0 + blockIdx.x) * a.chunk;
    const int lo = (int)max((long long)kmin, cs);
    const int hi = (int)min((long long)P1 + 1, cs + a.chunk);
    const float scale = rsqrtf((float)IKA_HD);
    float* myB = sB + warp * 16 * IKT_NB;
    const int wq = warp % 3;                                    // the warp's 16 rows of its tile's 48
    const bool wlive = 16 * wq < nq;

    // this thread's two rows (gid, gid + 8) of the warp's 16: query index, position
    const int ra = 16 * wq + gid, rb = ra + 8;
    const int qa = max(0, min(ra, nq - 1)), qb = max(0, min(rb, nq - 1));
    const int tl = mt > 0 ? t0 : tc0;                           // load rows of a live tile (an empty tile reads tile 0)
    const int Pa = P0 + ra / 3, Pb = P0 + rb / 3;
    // Q fragments (hi / lo) for the 8 k-steps, R fragments (hi / lo) for the bias MMA
    uint32_t qh[8][4], rh[4], rl[4];
    __half* myQl = sQl + warp * 16 * IKT_KS;
    {
        const float* qra = a.Qf + ((size_t)(tl + qa / 3) * NQ + 3 * kvh + qa % 3) * IKA_HD;
        const float* qrb = a.Qf + ((size_t)(tl + qb / 3) * NQ + 3 * kvh + qb % 3) * IKA_HD;
        #pragma unroll
        for (int kk = 0; kk < 8; ++kk) {
            const float2 x0 = *reinterpret_cast<const float2*>(qra + 16 * kk + 2 * tig);
            const float2 x1 = *reinterpret_cast<const float2*>(qrb + 16 * kk + 2 * tig);
            const float2 x2 = *reinterpret_cast<const float2*>(qra + 16 * kk + 8 + 2 * tig);
            const float2 x3 = *reinterpret_cast<const float2*>(qrb + 16 * kk + 8 + 2 * tig);
            uint32_t l0, l1, l2, l3;
            ika_split_h(x0.x, x0.y, qh[kk][0], l0);
            ika_split_h(x1.x, x1.y, qh[kk][1], l1);
            ika_split_h(x2.x, x2.y, qh[kk][2], l2);
            ika_split_h(x3.x, x3.y, qh[kk][3], l3);
            if constexpr (!SP) {
                *reinterpret_cast<uint32_t*>(myQl + gid * IKT_KS + 16 * kk + 2 * tig) = l0;
                *reinterpret_cast<uint32_t*>(myQl + (gid + 8) * IKT_KS + 16 * kk + 2 * tig) = l1;
                *reinterpret_cast<uint32_t*>(myQl + gid * IKT_KS + 16 * kk + 8 + 2 * tig) = l2;
                *reinterpret_cast<uint32_t*>(myQl + (gid + 8) * IKT_KS + 16 * kk + 8 + 2 * tig) = l3;
            }
        }
        const float* rra = a.Rf + ((size_t)(tl + qa / 3) * NQ + 3 * kvh + qa % 3) * IKA_DREL;
        const float* rrb = a.Rf + ((size_t)(tl + qb / 3) * NQ + 3 * kvh + qb % 3) * IKA_DREL;
        const float2 y0 = *reinterpret_cast<const float2*>(rra + 2 * tig);
        const float2 y1 = *reinterpret_cast<const float2*>(rrb + 2 * tig);
        const float2 y2 = *reinterpret_cast<const float2*>(rra + 8 + 2 * tig);
        const float2 y3 = *reinterpret_cast<const float2*>(rrb + 8 + 2 * tig);
        ika_split_b(y0.x, y0.y, rh[0], rl[0]);
        ika_split_b(y1.x, y1.y, rh[1], rl[1]);
        ika_split_b(y2.x, y2.y, rh[2], rl[2]);
        ika_split_b(y3.x, y3.y, rh[3], rl[3]);
    }
    float o[16][4];
    #pragma unroll
    for (int n = 0; n < 16; ++n)
        #pragma unroll
        for (int r = 0; r < 4; ++r) o[n][r] = 0.f;
    float m_a = -INFINITY, m_b = -INFINITY, l_a = 0.f, l_b = 0.f;

    for (int kb = (lo / IKA_SUB) * IKA_SUB; kb < hi; kb += IKA_SUB) {
        __syncthreads();
        // K / V rows kb..kb+63 (16-B chunks; invalid rows zero-filled)
        for (int i = threadIdx.x; i < 64 * 16; i += 192) {
            const int r = i >> 4, ch = i & 15, kp = kb + r;
            const bool ok = kp >= lo && kp < hi;
            const size_t g = (size_t)((ok ? kp : lo) & a.cap_mask) * IKP_KVW(NQ) + kvh * IKA_HD + 8 * ch;
            ika_cp16(sK + r * IKT_KS + 8 * ch, a.kc + g, ok);
            ika_cp16(sV + r * IKT_KS + 8 * ch, a.vc + g, ok);
        }
        asm volatile("cp.async.commit_group;" ::: "memory");
        const int dminc = P0c - (kb + IKA_SUB - 1);           // the CTA's columns: distances dminc .. dminc + 95
        const int dmin = dminc + 16 * tt;                       // this warp's tile: its 80 columns start 16 tt later
        for (int i = threadIdx.x; i < IKT2_NB * IKA_DREL; i += 192) {
            const int c = i >> 4, dd = i & 15, dist = dminc + c;
            const float v = (dist >= 0 && dist < a.ext) ? a.proj[(size_t)dd * a.ext + dist] : 0.f;
            sPJ[c * IKT_PJS + dd] = (uint16_t)(__float_as_uint(v) >> 16);   // proj is bf16-valued: exact
        }
        asm volatile("cp.async.wait_group 0;" ::: "memory");
        __syncthreads();
        if (!wlive) continue;
        // bias tile [16 rows][80 distances] -> warp-private smem
        #pragma unroll
        for (int n = 0; n < IKT_NB / 8; n += 2) {
            uint32_t b0, b1, b2, b3;
            ika_ldsm4(b0, b1, b2, b3, sPJ + (16 * tt + 8 * n + (lane >> 4) * 8 + (lane & 7)) * IKT_PJS + ((lane >> 3) & 1) * 8);
            float c0[4] = {0.f, 0.f, 0.f, 0.f}, c1[4] = {0.f, 0.f, 0.f, 0.f};
            ika_mma_bf(c0, rh[0], rh[1], rh[2], rh[3], b0, b1);
            ika_mma_bf(c0, rl[0], rl[1], rl[2], rl[3], b0, b1);
            ika_mma_bf(c1, rh[0], rh[1], rh[2], rh[3], b2, b3);
            ika_mma_bf(c1, rl[0], rl[1], rl[2], rl[3], b2, b3);
            *reinterpret_cast<float2*>(myB + gid * IKT_NB + 8 * n + 2 * tig) = make_float2(c0[0], c0[1]);
            *reinterpret_cast<float2*>(myB + (gid + 8) * IKT_NB + 8 * n + 2 * tig) = make_float2(c0[2], c0[3]);
            *reinterpret_cast<float2*>(myB + gid * IKT_NB + 8 * n + 8 + 2 * tig) = make_float2(c1[0], c1[1]);
            *reinterpret_cast<float2*>(myB + (gid + 8) * IKT_NB + 8 * n + 8 + 2 * tig) = make_float2(c1[2], c1[3]);
        }
        __syncwarp();
        // S = Q K^T
        float s[8][4];
        #pragma unroll
        for (int n = 0; n < 8; ++n)
            #pragma unroll
            for (int r = 0; r < 4; ++r) s[n][r] = 0.f;
        #pragma unroll
        for (int kk = 0; kk < 8; ++kk) {
            uint32_t ql[4] = {0u, 0u, 0u, 0u};
            if constexpr (!SP)
                ika_ldsm4(ql[0], ql[1], ql[2], ql[3], myQl + ((lane & 7) + ((lane >> 3) & 1) * 8) * IKT_KS + 16 * kk + (lane >> 4) * 8);
            #pragma unroll
            for (int n = 0; n < 8; n += 2) {
                uint32_t b0, b1, b2, b3;
                ika_ldsm4(b0, b1, b2, b3, sK + (8 * n + (lane >> 4) * 8 + (lane & 7)) * IKT_KS + 16 * kk + ((lane >> 3) & 1) * 8);
                ika_mma_h(s[n], qh[kk][0], qh[kk][1], qh[kk][2], qh[kk][3], b0, b1);
                if constexpr (!SP) ika_mma_h(s[n], ql[0], ql[1], ql[2], ql[3], b0, b1);
                ika_mma_h(s[n + 1], qh[kk][0], qh[kk][1], qh[kk][2], qh[kk][3], b2, b3);
                if constexpr (!SP) ika_mma_h(s[n + 1], ql[0], ql[1], ql[2], ql[3], b2, b3);
            }
        }
        // scale + bias + mask; row maxima
        float mxa = -INFINITY, mxb = -INFINITY;
        #pragma unroll
        for (int n = 0; n < 8; ++n)
            #pragma unroll
            for (int e = 0; e < 2; ++e) {
                const int kp = kb + 8 * n + 2 * tig + e;
                const bool kin = kp >= lo && kp < hi;
                const int da = Pa - kp, db = Pb - kp;
                const bool oka = kin && da >= 0 && (a.window == 0 || da < a.window);
                const bool okb = kin && db >= 0 && (a.window == 0 || db < a.window);
                s[n][e] = oka ? fmaf(s[n][e], scale, myB[gid * IKT_NB + (da - dmin)]) : -INFINITY;
                s[n][2 + e] = okb ? fmaf(s[n][2 + e], scale, myB[(gid + 8) * IKT_NB + (db - dmin)]) : -INFINITY;
                mxa = fmaxf(mxa, s[n][e]);
                mxb = fmaxf(mxb, s[n][2 + e]);
            }
        mxa = fmaxf(mxa, __shfl_xor_sync(0xffffffffu, mxa, 1)); mxa = fmaxf(mxa, __shfl_xor_sync(0xffffffffu, mxa, 2));
        mxb = fmaxf(mxb, __shfl_xor_sync(0xffffffffu, mxb, 1)); mxb = fmaxf(mxb, __shfl_xor_sync(0xffffffffu, mxb, 2));
        // a row with nothing visible keeps its state (fold 1, p 0)
        const float mna = mxa == -INFINITY ? m_a : fmaxf(m_a, mxa);
        const float mnb = mxb == -INFINITY ? m_b : fmaxf(m_b, mxb);
        const float fa = mxa == -INFINITY ? 1.f : __expf(m_a - mna);
        const float fb = mxb == -INFINITY ? 1.f : __expf(m_b - mnb);
        float sa = 0.f, sb = 0.f;
        #pragma unroll
        for (int n = 0; n < 8; ++n) {   // (a row with nothing visible: p = 0, not exp(-inf - -inf))
            s[n][0] = mxa == -INFINITY ? 0.f : __expf(s[n][0] - mna); s[n][1] = mxa == -INFINITY ? 0.f : __expf(s[n][1] - mna);
            s[n][2] = mxb == -INFINITY ? 0.f : __expf(s[n][2] - mnb); s[n][3] = mxb == -INFINITY ? 0.f : __expf(s[n][3] - mnb);
            sa += s[n][0] + s[n][1];
            sb += s[n][2] + s[n][3];
        }
        sa += __shfl_xor_sync(0xffffffffu, sa, 1); sa += __shfl_xor_sync(0xffffffffu, sa, 2);
        sb += __shfl_xor_sync(0xffffffffu, sb, 1); sb += __shfl_xor_sync(0xffffffffu, sb, 2);
        if (mxa != -INFINITY) { l_a = l_a * fa + sa; m_a = mna; }
        if (mxb != -INFINITY) { l_b = l_b * fb + sb; m_b = mnb; }
        #pragma unroll
        for (int n = 0; n < 16; ++n) { o[n][0] *= fa; o[n][1] *= fa; o[n][2] *= fb; o[n][3] *= fb; }
        // O += P V   (P hi / lo f16; masked entries are exp(-inf) = 0)
        #pragma unroll
        for (int kk = 0; kk < 4; ++kk) {
            uint32_t ph[4], pl[4];
            ika_split_h(s[2 * kk][0], s[2 * kk][1], ph[0], pl[0]);
            ika_split_h(s[2 * kk][2], s[2 * kk][3], ph[1], pl[1]);
            ika_split_h(s[2 * kk + 1][0], s[2 * kk + 1][1], ph[2], pl[2]);
            ika_split_h(s[2 * kk + 1][2], s[2 * kk + 1][3], ph[3], pl[3]);
            #pragma unroll
            for (int n = 0; n < 16; n += 2) {
                uint32_t b0, b1, b2, b3;
                ika_ldsm4t(b0, b1, b2, b3, sV + (16 * kk + ((lane >> 3) & 1) * 8 + (lane & 7)) * IKT_KS + 8 * n + (lane >> 4) * 8);
                ika_mma_h(o[n], ph[0], ph[1], ph[2], ph[3], b0, b1);
                if constexpr (!SP) ika_mma_h(o[n], pl[0], pl[1], pl[2], pl[3], b0, b1);
                ika_mma_h(o[n + 1], ph[0], ph[1], ph[2], ph[3], b2, b3);
                if constexpr (!SP) ika_mma_h(o[n + 1], pl[0], pl[1], pl[2], pl[3], b2, b3);
            }
        }
    }
    if (!wlive) return;
    // epilogue: rows ra / rb (< nq)
    #pragma unroll
    for (int half = 0; half < 2; ++half) {
        const int r = half ? rb : ra;
        if (r >= nq) continue;
        const int t = t0 + r / 3, h = 3 * kvh + r % 3;
        const float mr = half ? m_b : m_a, lr = half ? l_b : l_a;
        if (nsplit == 1) {
            const float* y = a.Y + (size_t)t * a.ldy;
            const float sink = y[a.os + h];
            const float m = fmaxf(mr, sink);
            const float fold = __expf(mr - m);
            const float w = fold / (lr * fold + __expf(sink - m));
            if (a.og < 0) {
                float* fp = reinterpret_cast<float*>(a.out) + (size_t)t * NQ * IKA_HD + h * IKA_HD;
                #pragma unroll
                for (int n = 0; n < 16; ++n) {
                    const int dcol = 8 * n + 2 * tig;
                    *reinterpret_cast<float2*>(fp + dcol) = make_float2(o[n][2 * half] * w, o[n][2 * half + 1] * w);
                }
            } else {
                uint16_t* op = a.out + (size_t)t * NQ * IKA_HD + h * IKA_HD;
                #pragma unroll
                for (int n = 0; n < 16; ++n) {
                    const int dcol = 8 * n + 2 * tig;
                    const float2 gt = *reinterpret_cast<const float2*>(y + a.og + h * IKA_HD + dcol);
                    const float v0 = o[n][2 * half] * w * ika_sig(gt.x), v1 = o[n][2 * half + 1] * w * ika_sig(gt.y);
                    *reinterpret_cast<uint32_t*>(op + dcol) = (uint32_t)ika_f2b(v0) | ((uint32_t)ika_f2b(v1) << 16);
                }
            }
        } else {
            const size_t pi = ((size_t)t * NQ + h) * nsplit + blockIdx.x;
            if (tig == 0) { a.pm[pi] = mr; a.pl[pi] = lr; }
            #pragma unroll
            for (int n = 0; n < 16; ++n)
                *reinterpret_cast<float2*>(a.pacc + pi * IKA_HD + 8 * n + 2 * tig) = make_float2(o[n][2 * half], o[n][2 * half + 1]);
        }
    }
}

template <int NQ>
__device__ __forceinline__ void ikp_attn_mr_body(const InkAttnArgs& a, const int bx) {
    const int bz = 0;
    extern __shared__ __align__(16) unsigned char smraw[];
    const int warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
    const int kvh = blockIdx.y;
    const int t0 = bz * 16;
    const int mt = min(16, a.M - t0);
    const int nq = 3 * mt;
    const int qcap = 3 * min(16, a.M);                                // same for every CTA of the launch
    float* sQ = reinterpret_cast<float*>(smraw);                     // [qcap][128]
    float* sR = sQ + qcap * IKA_HD;                                   // [qcap][16]
    float* sP = sR + qcap * IKA_DREL;                                 // [16][80] proj columns
    __half* sK = reinterpret_cast<__half*>(sP + IKA_DREL * 80);       // [64][130]
    __half* sV = sK + IKA_SUB * IKA_KSTR;                             // [64][128]

    for (int i = threadIdx.x; i < nq * IKA_HD; i += blockDim.x) {
        const int qi = i / IKA_HD, d = i % IKA_HD;
        const int t = t0 + qi / 3, h = 3 * kvh + qi % 3;
        sQ[i] = a.Qf[((size_t)t * NQ + h) * IKA_HD + d];
    }
    for (int i = threadIdx.x; i < nq * IKA_DREL; i += blockDim.x) {
        const int qi = i / IKA_DREL, d = i % IKA_DREL;
        const int t = t0 + qi / 3, h = 3 * kvh + qi % 3;
        sR[i] = a.Rf[((size_t)t * NQ + h) * IKA_DREL + d];
    }
    const int P0 = a.p0 + t0, P1 = P0 + mt - 1;
    const int kmin = a.window ? max(0, P0 - a.window + 1) : 0;
    const long long cs = (long long)(a.c0 + bx) * a.chunk;
    const int lo = (int)max((long long)kmin, cs);
    const int hi = (int)min((long long)P1 + 1, cs + a.chunk);       // exclusive
    const float scale = rsqrtf((float)IKA_HD);

    float m_run[IKA_QPW], l_run[IKA_QPW], acc[IKA_QPW][4];
    #pragma unroll
    for (int j = 0; j < IKA_QPW; ++j) {
        m_run[j] = -INFINITY; l_run[j] = 0.f;
        #pragma unroll
        for (int d = 0; d < 4; ++d) acc[j][d] = 0.f;
    }
    for (int kb = (lo / IKA_SUB) * IKA_SUB; kb < hi; kb += IKA_SUB) {
        __syncthreads();
        // K / V subtile (rows outside [lo, hi) are zero: never read uninitialised cache)
        for (int i = threadIdx.x; i < IKA_SUB * 64; i += blockDim.x) {
            const int r = i >> 6, w2 = i & 63;     // 64 half2 per row
            const int kp = kb + r;
            __half2 kv2 = __float2half2_rn(0.f), vv2 = __float2half2_rn(0.f);
            if (kp >= lo && kp < hi) {
                const size_t base = (size_t)(kp & a.cap_mask) * IKP_KVW(NQ) + kvh * IKA_HD + 2 * w2;
                kv2 = *reinterpret_cast<const __half2*>(a.kc + base);
                vv2 = *reinterpret_cast<const __half2*>(a.vc + base);
            }
            *reinterpret_cast<__half2*>(sK + r * IKA_KSTR + 2 * w2) = kv2;
            *reinterpret_cast<__half2*>(sV + r * IKA_HD + 2 * w2) = vv2;
        }
        // proj columns for distances dmin .. dmin+79 (dmin = P0 - (kb + 63))
        const int dmin = P0 - (kb + IKA_SUB - 1);
        for (int i = threadIdx.x; i < IKA_DREL * 80; i += blockDim.x) {
            const int dd = i / 80, c = i % 80;
            const int dist = dmin + c;
            sP[i] = (dist >= 0 && dist < a.ext) ? a.proj[(size_t)dd * a.ext + dist] : 0.f;
        }
        __syncthreads();
        #pragma unroll
        for (int j = 0; j < IKA_QPW; ++j) {
            const int qi = warp + 8 * j;
            if (qi >= nq) break;
            const int P = P0 + qi / 3;
            const float* q = sQ + qi * IKA_HD;
            const float* rr = sR + qi * IKA_DREL;
            float s[2];
            #pragma unroll
            for (int u = 0; u < 2; ++u) {
                const int r = lane + 32 * u, kp = kb + r;
                const __half2* kr = reinterpret_cast<const __half2*>(sK + r * IKA_KSTR);
                float dot = 0.f;
                #pragma unroll 16
                for (int d2 = 0; d2 < IKA_HD / 2; ++d2) {
                    const float2 kf = __half22float2(kr[d2]);
                    dot = fmaf(q[2 * d2], kf.x, dot);
                    dot = fmaf(q[2 * d2 + 1], kf.y, dot);
                }
                const int dist = P - kp;
                float b = 0.f;
                const int col = dist - dmin;
                #pragma unroll
                for (int dd = 0; dd < IKA_DREL; ++dd) b = fmaf(rr[dd], sP[dd * 80 + col], b);
                const bool ok = kp >= lo && kp < hi && dist >= 0 && (a.window == 0 || dist < a.window);
                s[u] = ok ? fmaf(dot, scale, b) : -INFINITY;
            }
            const float msub = ika_wmax(fmaxf(s[0], s[1]));
            if (msub == -INFINITY) continue;          // nothing visible here: state untouched
            const float mnew = fmaxf(m_run[j], msub);
            const float fold = __expf(m_run[j] - mnew); // m_run = -inf -> 0
            const float e0 = __expf(s[0] - mnew), e1 = __expf(s[1] - mnew);
            l_run[j] = l_run[j] * fold + ika_wsum(e0 + e1);
            m_run[j] = mnew;
            float o0 = acc[j][0] * fold, o1 = acc[j][1] * fold, o2 = acc[j][2] * fold, o3 = acc[j][3] * fold;
            #pragma unroll 8
            for (int r = 0; r < IKA_SUB; ++r) {
                const float pr = __shfl_sync(0xffffffffu, r < 32 ? e0 : e1, r & 31);
                const uint2 vv = *reinterpret_cast<const uint2*>(sV + r * IKA_HD + 4 * lane);
                const float2 va = __half22float2(*reinterpret_cast<const __half2*>(&vv.x));
                const float2 vb = __half22float2(*reinterpret_cast<const __half2*>(&vv.y));
                o0 = fmaf(pr, va.x, o0); o1 = fmaf(pr, va.y, o1); o2 = fmaf(pr, vb.x, o2); o3 = fmaf(pr, vb.y, o3);
            }
            acc[j][0] = o0; acc[j][1] = o1; acc[j][2] = o2; acc[j][3] = o3;
        }
    }
    #pragma unroll
    for (int j = 0; j < IKA_QPW; ++j) {
        const int qi = warp + 8 * j;
        if (qi >= nq) break;
        const int t = t0 + qi / 3, h = 3 * kvh + qi % 3;
        int rch, rc0, nsplit;
        ikl_split(a.p0 + t, a.window, rch, rc0, nsplit);
        const int slot = a.c0 + bx - rc0;
        if (slot < 0 || slot >= nsplit) continue;            // not one of this row's chunks: the decode has no such CTA
        if (nsplit == 1) {
            const float* y = a.Y + (size_t)t * a.ldy;
            const float sink = y[a.os + h];
            const float m = fmaxf(m_run[j], sink);
            const float fold = __expf(m_run[j] - m);
            const float inv = 1.0f / (l_run[j] * fold + __expf(sink - m));
            const float4 gt = *reinterpret_cast<const float4*>(y + a.og + h * IKA_HD + 4 * lane);
            uint16_t* o = a.out + (size_t)t * NQ * IKA_HD + h * IKA_HD + 4 * lane;
            const float w = fold * inv;
            uint2 pk;
            pk.x = (uint32_t)ika_f2b(acc[j][0] * w * ika_sig(gt.x)) | ((uint32_t)ika_f2b(acc[j][1] * w * ika_sig(gt.y)) << 16);
            pk.y = (uint32_t)ika_f2b(acc[j][2] * w * ika_sig(gt.z)) | ((uint32_t)ika_f2b(acc[j][3] * w * ika_sig(gt.w)) << 16);
            *reinterpret_cast<uint2*>(o) = pk;
        } else {
            const size_t pi = (size_t)t * IKL_PSTR + (size_t)h * nsplit + slot;   // the lanes partial layout
            if (lane == 0) { a.pm[pi] = m_run[j]; a.pl[pi] = l_run[j]; }
            *reinterpret_cast<float4*>(a.pacc + pi * IKA_HD + 4 * lane) = make_float4(acc[j][0], acc[j][1], acc[j][2], acc[j][3]);
        }
    }
}

template <int NQ>
__device__ __forceinline__ void ikp_attn_prep_lanes(const InkPrepArgs a, const InkLaneSlot* __restrict__ tab,
        int slot, int nslots, const int* __restrict__ rinfo) {
    INK2_PDL_ENTRY();
    const int row = blockIdx.x, t = IKL_T(rinfo, row), r0 = row - t;
    const InkLaneSlot s = tab[IKL_LANE(rinfo, row) * nslots + slot];
    InkPrepArgs b = a;
    b.Y = a.Y + (size_t)r0 * a.ldy;
    b.Qf = a.Qf + (size_t)r0 * NQ * IKA_HD;
    b.Rf = a.Rf + (size_t)r0 * NQ * IKA_DREL;
    b.ring_k = s.ring[0]; b.ring_v = s.ring[1]; b.ring_write = 1;
    b.kc = s.kc; b.vc = s.vc; b.cap_mask = s.cap_mask;
    b.p0 = IKL_POS(rinfo, row) - t; b.M = t + 1;
    ikp_attn_prep_body<NQ>(b, t);
}

// grid (IKL_MAXS, 8 kv heads, n rows), block 256, smem attn_smem(1). CTAs past the row's split count exit.

template <int NQ>
__device__ __forceinline__ void ikp_attn_lanes(const InkAttnArgs a, const InkLaneSlot* __restrict__ tab,
        int slot, int nslots, const int* __restrict__ rinfo) {
    INK2_PDL_ENTRY();
    const int row = blockIdx.z;
    const int p = IKL_POS(rinfo, row);
    int chunk, c0, nsplit;
    ikl_split(p, a.window, chunk, c0, nsplit);
    if (nsplit > IKL_MAXS) __trap();
    if ((int)blockIdx.x >= nsplit) return;
    { int rs, rl; if (a.c0 == 0 && ikl_run_mr(rinfo, row, gridDim.z, a.window, rs, rl)) return; }  // S7: the run is ink_attn_lanes_mr's (a.c0 = 1: mr off)
    const InkLaneSlot s = tab[IKL_LANE(rinfo, row) * nslots + slot];
    InkAttnArgs b = a;
    b.Qf = a.Qf + (size_t)row * NQ * IKA_HD;
    b.Rf = a.Rf + (size_t)row * NQ * IKA_DREL;
    b.kc = s.kc; b.vc = s.vc; b.cap_mask = s.cap_mask;
    b.p0 = p; b.M = 1; b.chunk = chunk; b.c0 = c0;
    b.Y = a.Y + (size_t)row * a.ldy;
    b.out = a.out + (size_t)row * NQ * IKA_HD;
    b.pm = a.pm + (size_t)row * IKL_PSTR; b.pl = a.pl + (size_t)row * IKL_PSTR; b.pacc = a.pacc + (size_t)row * IKL_PSTR * IKA_HD;
    ikp_attn_body<NQ>(b, nsplit, blockIdx.x, 0);
}

// grid (n rows, NQ), block 128: merge the split partials of rows that used more than one split.

template <int NQ>
__device__ __forceinline__ void ikp_attn_combine_lanes(const InkAttnArgs a, const int* __restrict__ rinfo) {
    INK2_PDL_ENTRY();
    const int row = blockIdx.x;
    const int p = IKL_POS(rinfo, row);
    int chunk, c0, nsplit;
    ikl_split(p, a.window, chunk, c0, nsplit);
    if (nsplit <= 1) return;
    InkAttnArgs b = a;
    b.Y = a.Y + (size_t)row * a.ldy;
    b.out = a.out + (size_t)row * NQ * IKA_HD;
    b.pm = a.pm + (size_t)row * IKL_PSTR; b.pl = a.pl + (size_t)row * IKL_PSTR; b.pacc = a.pacc + (size_t)row * IKL_PSTR * IKA_HD;
    ikp_attn_combine_body<NQ>(b, nsplit, 0);
}

// grid (ceil(C / 256), n rows), block 256: static conv + residual of each row on its lane's ring `ri`.

template <int NQ>
__device__ __forceinline__ void ikp_attn_lanes_mr(const InkAttnArgs a, const InkLaneSlot* __restrict__ tab,
        int slot, int nslots, const int* __restrict__ rinfo) {
    INK2_PDL_ENTRY();
    const int row = blockIdx.z;
    if (IKL_T(rinfo, row) != 0) return;
    int s, L;
    if (!ikl_run_mr(rinfo, row, gridDim.z, a.window, s, L)) return;
    const int p = IKL_POS(rinfo, row);
    int chunk, c0, nsplit;
    ikl_split(p, a.window, chunk, c0, nsplit);
    int cl, c0l, nsl;
    ikl_split(p + L - 1, a.window, cl, c0l, nsl);
    if (c0l + nsl - c0 > IKL_MAXS + 1) __trap();
    if ((int)blockIdx.x >= c0l + nsl - c0) return;
    const InkLaneSlot sl = tab[IKL_LANE(rinfo, row) * nslots + slot];
    InkAttnArgs b = a;
    b.Qf = a.Qf + (size_t)row * NQ * IKA_HD;
    b.Rf = a.Rf + (size_t)row * NQ * IKA_DREL;
    b.kc = sl.kc; b.vc = sl.vc; b.cap_mask = sl.cap_mask;
    b.p0 = p; b.M = L; b.chunk = chunk; b.c0 = c0;
    b.Y = a.Y + (size_t)row * a.ldy;
    b.out = a.out + (size_t)row * NQ * IKA_HD;
    b.pm = a.pm + (size_t)row * IKL_PSTR; b.pl = a.pl + (size_t)row * IKL_PSTR; b.pacc = a.pacc + (size_t)row * IKL_PSTR * IKA_HD;
    ikp_attn_mr_body<NQ>(b, blockIdx.x);
}

// ---- entries (one per head width) ----
extern "C" __global__ __launch_bounds__(1024) void ink_tp24_attn_prep(const InkPrepArgs a) { INK2_PDL_ENTRY(); ikp_attn_prep_body<24>(a, blockIdx.x); }
